import services from "./services.json";
import { USER_AGENT } from "../constants.ts";
import type { Secret } from "../core/secret.ts";
import { defineManualRecipe, RESOURCE_NAME, type ManualRecipe, type RecipeId } from "../recipes/types.ts";

// Every service Sikrets can keep a key for (generated by scripts/services.ts). Services without a
// hand-written recipe get a generic one: paste the key, check it against the service's API when we
// know a safe endpoint, store it, and hand the project a stand-in.

/** How the service expects its key: Authorization bearer, a named header, a query parameter, basic auth, OAuth, or not known. */
export type ServiceAuth = "bearer" | "header" | "query" | "basic" | "oauth" | "unknown";

export interface Service {
  id: string;
  name: string;
  category: string;
  auth: ServiceAuth;
  header?: string;
  query?: string;
  /** A read-only GET on the service's own domain; a 401 there means the key is wrong. */
  verify?: string;
  docs?: string;
  website?: string;
  terraform?: string;
  sources: string[];
}

export const SERVICES = services as Service[];
const byId = new Map(SERVICES.map((s) => [s.id, s]));

export const service = (id: string) => byId.get(id);

/** Sends the key the way the service expects, to the service's own API; only a 401 counts as a wrong key. */
async function check(s: Service, key: Secret): Promise<void> {
  if (!s.verify) return;
  const url = new URL(s.verify);
  const headers: Record<string, string> = { "User-Agent": USER_AGENT, Accept: "application/json" };
  if (s.auth === "bearer") headers.Authorization = `Bearer ${key.reveal()}`;
  else if (s.auth === "header" && s.header) headers[s.header] = key.reveal();
  else if (s.auth === "query" && s.query) url.searchParams.set(s.query, key.reveal());
  else return;
  let status: number;
  try {
    // No redirects: a key must never follow a redirect to another host.
    status = (await fetch(url, { headers, redirect: "manual", signal: AbortSignal.timeout(15_000) })).status;
  } catch {
    return; // offline or the endpoint moved: storing an unchecked key beats blocking
  }
  if (status === 401) throw new Error(`${s.name} rejected this key (401): it's mistyped, revoked or expired`);
}

const steps = (s: Service): string[] =>
  s.auth === "oauth"
    ? [`Sign in to ${s.name} and create a personal access token (or API key) for this project`, "Copy it and paste it here"]
    : s.auth === "basic"
      ? [`Sign in to ${s.name} and create an API token or app password for this project`, "Copy it and paste it here"]
      : [`Sign in to ${s.name} and create an API key for this project (usually under Settings → API or Developers)`, "Copy it (it may be shown only once) and paste it here"];

const keyPage = (s: Service) => s.docs ?? s.website ?? `https://duckduckgo.com/?q=${encodeURIComponent(`${s.name} create API key`)}`;

/** The generic recipe for a catalog service, e.g. "stripe/api-key". */
export function serviceRecipe(id: string): ManualRecipe | undefined {
  const [sid, kind] = id.split("/");
  const s = kind === "api-key" ? service(sid!) : undefined;
  if (!s) return undefined;
  return defineManualRecipe({
    id: `${s.id}/api-key` as RecipeId,
    provider: s.id,
    summary: `A ${s.name} API key you create in its dashboard`,
    defaultName: RESOURCE_NAME.test(s.id) ? s.id : `x-${s.id}`.slice(0, 31).replace(/-+$/, ""),
    inputs: {},
    requires: [],
    outputs: { api_key: { description: `${s.name} API key`, env: "API_KEY", sensitive: true } },
    secret: "api_key",
    pattern: /^\S{8,}$/,
    instructions: { url: keyPage(s), steps: steps(s) },
    estimate: () => `billed by ${s.name}`,
    verify: (key) => check(s, key),
  });
}
